/**
 * Formula neutralization, the rule of lib/prospecting/exportar.ts: a cell that starts
 * with = + - @ TAB or CR gets a leading ' unless the WHOLE value is a phone number,
 * so E.164 phones stay intact and "+(HYPERLINK(...))" does not slip through.
 */
const TELEFONE_FORMATADO = /^\+[\d\s().-]+$/;
function neutralizarFormula(texto: string): string {
  if (!/^[=+\-@\t\r]/.test(texto)) return texto;
  if (TELEFONE_FORMATADO.test(texto)) return texto;
  return `'${texto}`;
}

/** RFC 4180 plus formula neutralization. */
function csvEscape(valor: unknown): string {
  if (valor === null || valor === undefined) return "";
  const texto = neutralizarFormula(typeof valor === "string" ? valor : String(valor));
  if (/[",\n\r]/.test(texto)) return `"${texto.replace(/"/g, '""')}"`;
  return texto;
}

// Same gap in the shared exporter: exempt + or - only when the WHOLE value is a number or phone.
const NUMERO_OU_TELEFONE = /^[+-]?[\d\s().-]+$/;
function pareceFormula(texto: string): boolean {
  const c = texto[0];
  if (c === "=" || c === "@" || c === "\t" || c === "\r") return true;
  if (c === "+" || c === "-") return !NUMERO_OU_TELEFONE.test(texto);
  return false;
}

